begin;
insert into auth.users(id,email) values ('11000000-0000-4000-8000-000000000091','manage-a@example.invalid'),('11000000-0000-4000-8000-000000000092','manage-b@example.invalid'),('11000000-0000-4000-8000-000000000093','manage-c@example.invalid');
insert into public.couples(id,name,created_by) values ('21000000-0000-4000-8000-000000000091','Game test','11000000-0000-4000-8000-000000000091');
insert into public.couple_members(couple_id,user_id) values ('21000000-0000-4000-8000-000000000091','11000000-0000-4000-8000-000000000091'),('21000000-0000-4000-8000-000000000091','11000000-0000-4000-8000-000000000092');
set local role authenticated;
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000091',true);
do $$ declare m uuid; t uuid; r uuid; begin
 insert into public.couple_game_matches(couple_id,created_by,kind) values('21000000-0000-4000-8000-000000000091',auth.uid(),'bingo') returning id into m;
 perform set_config('test.match',m::text,true);
 update public.couple_game_matches set last_move=2 where id=m;
 update public.couple_game_matches set last_move=-2 where id=m;
 if not exists(select 1 from public.couple_game_matches where id=m and board=array_fill(0,array[25]) and move_count=0) then raise exception 'Reset failed';end if;
 update public.couple_game_matches set last_move=1 where id=m;
 if not exists(select 1 from public.couple_game_matches where id=m and board[2]=1 and move_count=1) then raise exception 'Move after reset failed';end if;
 insert into public.couple_game_matches(couple_id,created_by,opponent_id,kind) values('21000000-0000-4000-8000-000000000091',auth.uid(),'11000000-0000-4000-8000-000000000092','tic') returning id into t;
 update public.couple_game_matches set last_move=0 where id=t;
 begin update public.couple_game_matches set last_move=1 where id=t;raise exception 'Double turn accepted';exception when raise_exception then if sqlerrm='Double turn accepted' then raise;end if;end;
 update public.couple_game_matches set archived_at=now() where id=t;
 if not exists(select 1 from public.couple_game_matches where id=t and archived_at is not null) then raise exception 'Archive while off-turn failed';end if;
 insert into public.couple_game_results(couple_id,user_id,kind,score) values('21000000-0000-4000-8000-000000000091',auth.uid(),'trivia',20) returning id into r;
 perform set_config('test.result',r::text,true);
end $$;
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000092',true);
do $$ begin
 begin update public.couple_game_matches set archived_at=now() where id=current_setting('test.match')::uuid;raise exception 'Partner archive allowed';exception when raise_exception then if sqlerrm='Partner archive allowed' then raise;end if;end;
 update public.couple_game_results set archived_at=now() where id=current_setting('test.result')::uuid;
 if found then raise exception 'Partner result archive allowed';end if;
 update public.couple_game_matches set last_move=-2 where id=current_setting('test.match')::uuid;
 if not exists(select 1 from public.couple_game_matches where id=current_setting('test.match')::uuid and move_count=0) then raise exception 'Partner reset failed';end if;
end $$;
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000091',true);
update public.couple_game_matches set archived_at=now() where id=current_setting('test.match')::uuid;
update public.couple_game_results set archived_at=now() where id=current_setting('test.result')::uuid;
insert into public.couple_game_matches(couple_id,created_by,kind) values('21000000-0000-4000-8000-000000000091',auth.uid(),'bingo');
do $$ begin if not exists(select 1 from public.couple_game_results where id=current_setting('test.result')::uuid and archived_at is not null) then raise exception 'Result archive failed';end if;end $$;
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000093',true);
do $$ begin if exists(select 1 from public.couple_game_matches) then raise exception 'Privacy failed';end if;end $$;
reset role;
rollback;
select 'Game reset, archive, authorization and fresh bingo passed' as result;
